"""Per-update Jimu Reward-WM-v2 rollout diagnostics."""

from __future__ import annotations

import csv
import json
import shutil
import subprocess
from pathlib import Path
from typing import Any

import numpy as np
from PIL import Image, ImageDraw


ROW_TITLES = (
    "RGB generated by Jimu Reward WM v2",
    "Tactile image encoded as signed [dx, dy, dz]",
    "Motion image used to condition Jimu Reward WM v2",
    "Motion foreground projected on generated RGB",
)


def resolve_ffmpeg_executable(ffmpeg_bin: str = "ffmpeg") -> str | None:
    """Resolve a system ffmpeg or imageio-ffmpeg's bundled executable."""

    executable = shutil.which(ffmpeg_bin)
    if executable is not None:
        return executable
    try:
        import imageio_ffmpeg

        executable = imageio_ffmpeg.get_ffmpeg_exe()
    except (ImportError, RuntimeError):
        return None
    return executable if Path(executable).is_file() else None


def motion_overlay(
    rgb_panel: np.ndarray,
    motion_panel: np.ndarray,
    *,
    background: int,
) -> np.ndarray:
    """Highlight the renderer foreground on its frame-aligned RGB panel."""

    rgb = np.asarray(rgb_panel, dtype=np.uint8)
    motion = np.asarray(motion_panel, dtype=np.uint8)
    if rgb.shape != motion.shape or rgb.ndim != 3 or rgb.shape[-1] != 3:
        raise ValueError(
            "RGB and motion panels must be aligned HWC uint8 arrays: "
            f"rgb={rgb.shape} motion={motion.shape}"
        )
    mask = np.any(motion != int(background), axis=-1)
    result = rgb.copy()
    highlight = np.empty_like(result)
    highlight[...] = (255, 40, 210)
    result[mask] = (
        0.35 * result[mask].astype(np.float32)
        + 0.65 * highlight[mask].astype(np.float32)
    ).astype(np.uint8)
    return result


def _title_row(row: np.ndarray, title: str) -> np.ndarray:
    image = Image.fromarray(np.asarray(row, dtype=np.uint8).copy())
    draw = ImageDraw.Draw(image)
    draw.rectangle((0, 0, image.width - 1, 22), fill=(0, 0, 0))
    draw.text((6, 5), title, fill=(255, 255, 255))
    return np.asarray(image)


def compose_rollout_frame(
    rgb_panel: np.ndarray,
    tactile_panel: np.ndarray,
    motion_panel: np.ndarray,
    *,
    motion_background: int,
    update_index: int,
    frame_index: int,
    probability: float,
    label: int,
    frame_reward: float,
    cumulative_reward: float,
    running_success_probability_mean: float,
    running_success_label_rate: float,
) -> np.ndarray:
    """Build one annotated RGB/tactile/motion/overlay diagnostic frame."""

    panels = [
        np.asarray(rgb_panel, dtype=np.uint8),
        np.asarray(tactile_panel, dtype=np.uint8),
        np.asarray(motion_panel, dtype=np.uint8),
    ]
    if any(panel.shape != panels[0].shape for panel in panels[1:]):
        raise ValueError(f"Diagnostic panels are not aligned: {[p.shape for p in panels]}")
    overlay = motion_overlay(
        panels[0], panels[2], background=motion_background
    )
    rows = [
        _title_row(panel, title)
        for panel, title in zip([*panels, overlay], ROW_TITLES, strict=True)
    ]
    body = np.concatenate(rows, axis=0)
    footer_height = 88
    image = Image.new(
        "RGB", (body.shape[1], body.shape[0] + footer_height), (12, 16, 28)
    )
    image.paste(Image.fromarray(body), (0, 0))
    draw = ImageDraw.Draw(image)
    draw.text(
        (7, body.shape[0] + 5),
        f"update={update_index:04d} frame={frame_index:03d} "
        f"chunk={(frame_index - 1) // 16 + 1:02d}",
        fill=(255, 255, 255),
    )
    draw.text(
        (7, body.shape[0] + 25),
        f"RM real-time p_success={probability:.5f}  binary_label={int(label)}  "
        f"GRPO direct_frame_reward={frame_reward:+.0f}",
        fill=(255, 255, 255),
    )
    draw.text(
        (7, body.shape[0] + 47),
        f"running_p_success_mean={running_success_probability_mean:.5f}  "
        f"running_binary_success_rate={running_success_label_rate:.5f}",
        fill=(255, 255, 255),
    )
    draw.text(
        (7, body.shape[0] + 69),
        f"GRPO cumulative_trajectory_reward={cumulative_reward:.0f}",
        fill=(255, 255, 255),
    )
    return np.ascontiguousarray(np.asarray(image))


class JimuRolloutVideoWriter:
    """Stream one sampled Shiguan trajectory per update to an H.264 video."""

    def __init__(
        self,
        output_dir: str | Path,
        *,
        fps: int = 10,
        motion_background: int = 190,
        ffmpeg_bin: str = "ffmpeg",
    ) -> None:
        self.output_dir = Path(output_dir)
        self.fps = int(fps)
        self.motion_background = int(motion_background)
        self.ffmpeg = resolve_ffmpeg_executable(ffmpeg_bin)
        if self.fps <= 0:
            raise ValueError("rollout visualization fps must be positive")
        if not 0 <= self.motion_background <= 255:
            raise ValueError("motion_background must be in [0,255]")
        if self.ffmpeg is None:
            raise FileNotFoundError(f"Could not find {ffmpeg_bin!r} on PATH")
        self.output_dir.mkdir(parents=True, exist_ok=True)
        self._process: subprocess.Popen | None = None
        self._update_index: int | None = None
        self._sample_env_index: int | None = None
        self._frame_count = 0
        self._cumulative_reward = 0.0
        self._running_probability_sum = 0.0
        self._running_label_sum = 0
        self._probabilities: list[float] = []
        self._labels: list[int] = []
        self._frame_rewards: list[float] = []
        self._reset_metadata: dict[str, Any] = {}
        self._video_path: Path | None = None
        self._partial_path: Path | None = None

    @property
    def active(self) -> bool:
        return self._update_index is not None

    def begin(
        self,
        *,
        update_index: int,
        sample_env_index: int,
        reset_metadata: dict[str, Any] | None = None,
    ) -> None:
        if self.active:
            raise RuntimeError("Previous Jimu rollout visualization is still active")
        self._update_index = int(update_index)
        self._sample_env_index = int(sample_env_index)
        self._frame_count = 0
        self._cumulative_reward = 0.0
        self._running_probability_sum = 0.0
        self._running_label_sum = 0
        self._probabilities = []
        self._labels = []
        self._frame_rewards = []
        self._reset_metadata = dict(reset_metadata or {})
        update_dir = self.output_dir / f"update_{self._update_index:04d}"
        update_dir.mkdir(parents=True, exist_ok=True)
        stem = f"sample_env_{self._sample_env_index:02d}"
        self._video_path = update_dir / f"{stem}.mp4"
        self._partial_path = update_dir / f"{stem}.partial.mp4"

    def _open_encoder(self, width: int, height: int) -> None:
        if self._partial_path is None:
            raise RuntimeError("Call begin before append")
        command = [
            str(self.ffmpeg),
            "-hide_banner",
            "-loglevel",
            "error",
            "-y",
            "-f",
            "rawvideo",
            "-pix_fmt",
            "rgb24",
            "-s:v",
            f"{width}x{height}",
            "-r",
            str(self.fps),
            "-i",
            "-",
            "-an",
            "-c:v",
            "libx264",
            "-preset",
            "veryfast",
            "-crf",
            "23",
            "-pix_fmt",
            "yuv420p",
            str(self._partial_path),
        ]
        self._process = subprocess.Popen(command, stdin=subprocess.PIPE)

    def append(
        self,
        *,
        rgb_panel_video: np.ndarray,
        tactile_panel_video: np.ndarray,
        motion_panel_video: np.ndarray,
        probabilities: np.ndarray,
        labels: np.ndarray,
        frame_rewards: np.ndarray,
    ) -> None:
        if not self.active:
            raise RuntimeError("Call begin before append")
        rgb = np.asarray(rgb_panel_video, dtype=np.uint8)
        tactile = np.asarray(tactile_panel_video, dtype=np.uint8)
        motion = np.asarray(motion_panel_video, dtype=np.uint8)
        probability = np.asarray(probabilities, dtype=np.float32).reshape(-1)
        label = np.asarray(labels, dtype=np.int64).reshape(-1)
        reward = np.asarray(frame_rewards, dtype=np.float32).reshape(-1)
        expected = rgb.shape[0]
        if rgb.ndim != 4 or rgb.shape[-1] != 3:
            raise ValueError(f"Expected RGB video [T,H,W,3], got {rgb.shape}")
        if tactile.shape != rgb.shape or motion.shape != rgb.shape:
            raise ValueError(
                f"Audit videos must align: rgb={rgb.shape} "
                f"tactile={tactile.shape} motion={motion.shape}"
            )
        if not all(len(value) == expected for value in (probability, label, reward)):
            raise ValueError("Reward diagnostics must contain one value per frame")

        for index in range(expected):
            self._frame_count += 1
            self._cumulative_reward += float(reward[index])
            self._running_probability_sum += float(probability[index])
            self._running_label_sum += int(label[index])
            running_probability_mean = (
                self._running_probability_sum / self._frame_count
            )
            running_label_rate = self._running_label_sum / self._frame_count
            frame = compose_rollout_frame(
                rgb[index],
                tactile[index],
                motion[index],
                motion_background=self.motion_background,
                update_index=int(self._update_index),
                frame_index=self._frame_count,
                probability=float(probability[index]),
                label=int(label[index]),
                frame_reward=float(reward[index]),
                cumulative_reward=self._cumulative_reward,
                running_success_probability_mean=running_probability_mean,
                running_success_label_rate=running_label_rate,
            )
            if self._process is None:
                self._open_encoder(frame.shape[1], frame.shape[0])
            assert self._process is not None and self._process.stdin is not None
            self._process.stdin.write(frame.tobytes())
            self._probabilities.append(float(probability[index]))
            self._labels.append(int(label[index]))
            self._frame_rewards.append(float(reward[index]))

    @staticmethod
    def _json_safe(value: Any) -> Any:
        if isinstance(value, dict):
            return {str(key): JimuRolloutVideoWriter._json_safe(item) for key, item in value.items()}
        if isinstance(value, (list, tuple)):
            return [JimuRolloutVideoWriter._json_safe(item) for item in value]
        if isinstance(value, np.ndarray):
            return value.tolist()
        if isinstance(value, np.generic):
            return value.item()
        if isinstance(value, (str, int, float, bool)) or value is None:
            return value
        return str(value)

    def finish(self, *, success: bool, trajectory_return: float) -> Path:
        if not self.active or self._process is None or self._video_path is None:
            raise RuntimeError("Cannot finish an empty Jimu rollout visualization")
        assert self._process.stdin is not None and self._partial_path is not None
        self._process.stdin.close()
        return_code = self._process.wait()
        if return_code != 0:
            raise RuntimeError(f"ffmpeg failed with exit code {return_code}")
        self._partial_path.replace(self._video_path)
        manifest = {
            "update": self._update_index,
            "sample_env_index": self._sample_env_index,
            "frames": self._frame_count,
            "fps": self.fps,
            "success": bool(success),
            "trajectory_return": float(trajectory_return),
            "mean_success_probability": (
                self._running_probability_sum / self._frame_count
            ),
            "frame_success_rate": self._running_label_sum / self._frame_count,
            "probabilities": self._probabilities,
            "labels": self._labels,
            "frame_rewards": self._frame_rewards,
            "reward_semantics": (
                "direct binary success emitted at the successful chunk's "
                "last action"
            ),
            "reset_metadata": self._json_safe(self._reset_metadata),
            "video": self._video_path.name,
            "rows": list(ROW_TITLES),
        }
        manifest_path = self._video_path.with_suffix(".json")
        manifest_path.write_text(
            json.dumps(manifest, indent=2, ensure_ascii=False), encoding="utf-8"
        )
        index_path = self.output_dir / "index.csv"
        write_header = not index_path.exists()
        with index_path.open("a", newline="", encoding="utf-8") as stream:
            writer = csv.DictWriter(
                stream,
                fieldnames=(
                    "update",
                    "sample_env_index",
                    "frames",
                    "success",
                    "trajectory_return",
                    "mean_success_probability",
                    "frame_success_rate",
                    "video",
                    "manifest",
                ),
            )
            if write_header:
                writer.writeheader()
            writer.writerow(
                {
                    "update": self._update_index,
                    "sample_env_index": self._sample_env_index,
                    "frames": self._frame_count,
                    "success": int(bool(success)),
                    "trajectory_return": float(trajectory_return),
                    "mean_success_probability": (
                        self._running_probability_sum / self._frame_count
                    ),
                    "frame_success_rate": (
                        self._running_label_sum / self._frame_count
                    ),
                    "video": str(self._video_path),
                    "manifest": str(manifest_path),
                }
            )
        result = self._video_path
        self._clear()
        return result

    def abort(self) -> None:
        if self._process is not None:
            if self._process.stdin is not None and not self._process.stdin.closed:
                self._process.stdin.close()
            if self._process.poll() is None:
                self._process.terminate()
                self._process.wait()
        if self._partial_path is not None and self._partial_path.exists():
            self._partial_path.unlink()
        self._clear()

    def _clear(self) -> None:
        self._process = None
        self._update_index = None
        self._sample_env_index = None
        self._video_path = None
        self._partial_path = None
